REFS = json.load(open(os.path.join(DATA, "refs_master.json"), encoding="utf-8"))
RR = REFS["refs"]


def ph(x):
    return f"<ph>{x}</ph>"


def fmt_ref(r):
    a = (r["authors"] or "").strip().rstrip(".") + "."
    t = (r["title"] or "").strip().rstrip(".") + "."
    c = (r.get("container") or "").strip()
    yr = r.get("year")
    vol, iss, pg = r.get("volume"), r.get("issue"), r.get("pages")
    tail = ""
    if vol or pg:
        tail = f"<i>{c}</i>, {yr}"
        if vol: tail += f", {vol}"
        if iss: tail += f" ({iss})"
        if pg: tail += f", pp. {pg}" if ("-" in str(pg) or "–" in str(pg)) else f", article {pg}"
        tail += "."
    else:
        tail = f"{c}" + (f", {yr}" if yr and str(yr) not in c else "") + "."
        tail = tail.replace("..", ".")
    doi = ""
    if r.get("doi") and r.get("doi_status") in ("seen_in_source", "derived_mdpi_pattern", "from_author_cv"):
        doi = f" DOI: {r['doi']}."
    mark = " <sup>†</sup>" if r.get("level") in ("O", "V3") else ""
    return f"{a} {t} {tail}{doi}{mark}"


def ref_par(n, text):
    p = mk_p("", tabs=[("left", 907)], left=907, hanging=907, after=60, sz=26)
    p.append(mk_run(f"[{n}]", sz=26))
    r = OxmlElement("w:r"); r.append(OxmlElement("w:tab")); p.append(r)
    for rr in parse_inline(text, None, 26): p.append(rr)
    return p


